#ifndef EQEMU_HOUSING_GUILD_TROPHY_SOURCES_H
#define EQEMU_HOUSING_GUILD_TROPHY_SOURCES_H
#include "trophy_benefits_db.h"
#include "guild_trophy_wire.h"
namespace Housing::GuildTrophies {
using TrophyBenefits::Definition;using TrophyBenefits::Catalog;
using TrophyBenefits::Detail::Q;using TrophyBenefits::Detail::Number;using TrophyBenefits::Detail::Unhex;
struct Source {uint64_t custody=0,house=0;EstateId estate=0;std::string digest;};
// A narrow retained proof for the world's single shared billing owner. Created
// ONLY after the actual zone Scene loader validates the full source. Matching
// current rows does not grant placement/admission/withdrawal rights.
inline std::optional<Source> SourceProjection(Database& db,uint32_t guild,uint64_t custody,uint64_t house){
 if(!guild||guild==UINT32_MAX||!custody)return {};
 std::vector<std::string> queries;
 std::string host=house?"JOIN housing_house_item_scopes scope ON scope.custody_id=c.custody_id AND scope.house_id="+std::to_string(house)+" JOIN housing_house_locations loc ON loc.house_id=scope.house_id AND loc.location_kind=2 JOIN housing_live_item_custody hc ON hc.custody_id=loc.custody_id JOIN housing_live_placed_items hp ON hp.custody_id=hc.custody_id JOIN housing_estates e ON e.id=hc.estate_id ":"JOIN housing_estates e ON e.id=c.estate_id ";
 auto gate="e.active=1 AND e.owner_kind=3 AND e.owner_id="+std::to_string(guild)+" AND c.custody_id="+std::to_string(custody)+" AND r.state=1 AND NOT EXISTS (SELECT 1 FROM housing_live_item_storage st WHERE st.custody_id=c.custody_id AND st.stowed=1) AND NOT EXISTS (SELECT 1 FROM housing_crate_members cm WHERE cm.custody_id=c.custody_id) AND NOT EXISTS (SELECT 1 FROM housing_live_item_leases l WHERE l.character_id=c.owner_character_id AND l.pending_key IS NOT NULL)";
 if(!house)gate+=" AND NOT EXISTS (SELECT 1 FROM housing_house_item_scopes s WHERE s.custody_id=c.custody_id)";
 else gate+=" AND NOT EXISTS (SELECT 1 FROM housing_live_item_storage st WHERE st.custody_id=hc.custody_id AND st.stowed=1) AND NOT EXISTS (SELECT 1 FROM housing_crate_members cm WHERE cm.custody_id=hc.custody_id) AND NOT EXISTS (SELECT 1 FROM housing_live_item_leases l WHERE l.character_id=hc.owner_character_id AND l.pending_key IS NOT NULL)";
 auto root=Q(db,"SELECT e.id,c.*,p.*,r.*,e.owner_kind,e.owner_id,e.plot_id,e.active,n.*,cat.*,h.zone_id,h.zone_version,h.instance_id,i.zone,i.version,i.never_expires FROM housing_live_item_custody c JOIN housing_live_placed_items p ON p.custody_id=c.custody_id JOIN housing_live_placement_reservations r ON r.native_item_id=p.native_item_id AND r.custody_id=c.custody_id "+host+"JOIN housing_native_estates n ON n.ownership_estate_id=e.id AND n.plot_id=e.plot_id AND n.active=1 JOIN housing_catalogs cat ON cat.catalog_key=n.catalog_key JOIN housing_neighborhoods h ON h.id=n.neighborhood_id JOIN instance_list i ON i.id=h.instance_id WHERE "+gate+" FOR UPDATE");
 if(root.RowCount()!=1)return {};const auto estate=Number(root.begin()[0]);std::vector<uint8_t> bytes;
 auto append=[&](MySQLRequestResult& result){if(result.RowCount()!=1)return false;auto row=result.begin();for(uint32_t col=0;col<result.ColumnCount();++col){bytes.push_back(row[col]?1:0);if(row[col]){const auto size=result.LengthOfColumn(int(col));if(size>8*1024*1024||bytes.size()+size>32*1024*1024)return false;TrophyAnchorWire::Detail::Write(bytes,uint32_t(size));bytes.insert(bytes.end(),row[col],row[col]+size);}}return bytes.size()<=32*1024*1024;};
 // Use actual MySQL field lengths so every embedded BLOB byte is hashed.
 if(!append(root))return {};
 queries.push_back("SELECT SHA2(c.row_blob,256),SHA2(c.catalog_blob,256),SHA2(p.pose_blob,256),SHA2(r.source_row,256),HEX(r.content_binding_digest),SHA2(cat.definitions_blob,256),SHA2(cat.regions_blob,256) FROM housing_live_item_custody c JOIN housing_live_placed_items p ON p.custody_id=c.custody_id JOIN housing_live_placement_reservations r ON r.native_item_id=p.native_item_id JOIN housing_catalogs cat ON cat.catalog_key=r.catalog_key WHERE c.custody_id="+std::to_string(custody)+" FOR UPDATE");
 if(house){
  queries.push_back("SELECT scope.*,h.*,loc.*,i.*,profile.*,t.*,SHA2(profile.definitions_blob,256),SHA2(profile.regions_blob,256),HEX(profile.client_asset_sha256),HEX(profile.collision_map_sha256),HEX(profile.manifest_sha256),HEX(t.content_digest),hc.owner_character_id,hc.schema_descriptor,SHA2(hc.row_blob,256),SHA2(hc.catalog_blob,256),hp.*,SHA2(hp.pose_blob,256),hr.*,SHA2(hr.source_row,256),HEX(hr.content_binding_digest),n.*,route.zone,route.version,route.never_expires FROM housing_house_item_scopes scope JOIN housing_house_instances h ON h.house_id=scope.house_id JOIN housing_house_locations loc ON loc.house_id=h.house_id AND loc.location_kind=2 JOIN housing_house_interiors i ON i.house_id=h.house_id JOIN housing_house_room_profiles profile ON profile.house_id=h.house_id JOIN housing_live_placed_items p ON p.custody_id=scope.custody_id JOIN housing_interior_placement_reservations t ON t.native_item_id=p.native_item_id AND t.house_id=h.house_id JOIN housing_live_item_custody hc ON hc.custody_id=loc.custody_id JOIN housing_live_placed_items hp ON hp.custody_id=hc.custody_id JOIN housing_live_placement_reservations hr ON hr.native_item_id=hp.native_item_id JOIN housing_native_estates n ON n.native_id=i.native_estate_id AND n.active=1 JOIN instance_list route ON route.id=i.instance_id WHERE scope.house_id="+std::to_string(house)+" AND scope.custody_id="+std::to_string(custody)+" FOR UPDATE");
 }
 for(const auto& sql:queries){auto result=Q(db,sql);if(!append(result))return {};}
 std::array<uint8_t,32> hash{};if(!SHA256(bytes.data(),bytes.size(),hash.data()))return {};const char* hex="0123456789abcdef";std::string digest;for(auto c:hash){digest+=hex[c>>4];digest+=hex[c&15];}return Source{custody,house,estate,digest};
}
struct Candidate {uint32_t benefit=0;Source source;bool at_source=false;};
inline LiveItems::Result<std::vector<Candidate>> SourcesUnderTransaction(Database& db,const LiveItems::Lease& lease,LiveItems::InventorySessionFence& fence,uint32_t guild,const Catalog& catalog,const std::optional<TrophyBenefits::SelectionLocation>& location,const Scene::HouseScenePolicy* houses,const InteriorContent::ProfilePolicy* rooms,const CrateBinding::CustodyContext* crates){
 using Error=LiveItems::Error;std::vector<Candidate> out;if(catalog.empty())return {std::move(out),Error::None};
 try{
  auto inspect=[&](uint64_t custody,EstateId estate,uint32_t item,uint64_t house){const bool room=house!=0;for(const auto& [benefit,d]:catalog){if(d.placed_item_id!=item)continue;bool at=false;
   if(room){if(!houses||!rooms)continue;auto checked=Scene::Service::ReadTrophySourceUnderTransaction(db,lease,estate,house,custody,fence,*houses,*rooms,crates);if(!checked){if(checked.error==Error::DatabaseFailure)throw TrophyBenefits::Detail::Failure{checked.error};continue;}const auto& r=checked.value;if(!r.house||!r.room_profile||r.contents.size()!=1||r.contents[0].stored.stowed||r.contents[0].contained_in_crate||!r.contents[0].stored.placement||!r.contents[0].room)continue;if(location){const auto& a=location->route;const auto& b=r.context.source;at=a.zone_id==b.zone_id&&a.zone_version==b.zone_version&&a.instance_id==b.instance_id&&TrophyBenefits::Within(r.room_profile->region,r.room_profile->additional_regions,location->position);}}
   else{auto checked=Scene::Service::ReadTrophyYardSourceUnderTransaction(db,lease,estate,custody,fence,houses,crates);if(!checked){if(checked.error==Error::DatabaseFailure)throw TrophyBenefits::Detail::Failure{checked.error};continue;}const auto& r=checked.value;if(r.items.size()!=1||r.items[0].stored.stowed||r.items[0].contained_in_crate||!r.items[0].stored.placement)continue;if(location){const auto& a=location->route;const auto& b=r.route;at=a.zone_id==b.zone_id&&a.zone_version==b.zone_version&&a.instance_id==b.instance_id&&TrophyBenefits::Within(r.region,location->position);}}
   auto proof=SourceProjection(db,guild,custody,house);if(proof)out.push_back({benefit,std::move(*proof),at});
  }};
  // Inventory row is versioned; never decode item ID with guessed SQL offsets.
  auto collect=[&](bool room){auto rows=Q(db,room?"SELECT c.custody_id,e.id,c.schema_descriptor,HEX(c.row_blob),scope.house_id FROM housing_house_item_scopes scope JOIN housing_live_item_custody c ON c.custody_id=scope.custody_id JOIN housing_house_locations loc ON loc.house_id=scope.house_id AND loc.location_kind=2 JOIN housing_live_item_custody hc ON hc.custody_id=loc.custody_id JOIN housing_estates e ON e.id=hc.estate_id AND e.active=1 AND e.owner_kind=3 AND e.owner_id="+std::to_string(guild)+" ORDER BY c.custody_id LIMIT 1001 FOR UPDATE":"SELECT c.custody_id,e.id,c.schema_descriptor,HEX(c.row_blob) FROM housing_live_item_custody c JOIN housing_estates e ON e.id=c.estate_id AND e.active=1 AND e.owner_kind=3 AND e.owner_id="+std::to_string(guild)+" WHERE NOT EXISTS (SELECT 1 FROM housing_house_item_scopes s WHERE s.custody_id=c.custody_id) ORDER BY c.custody_id LIMIT 1001 FOR UPDATE");if(rows.RowCount()>1000)throw TrophyBenefits::Detail::Failure{Error::UnsupportedItem};for(auto row=rows.begin();row!=rows.end();++row){if(!row[2]||std::string(row[2])!=LiveItems::Service::SchemaDescriptor())continue;auto decoded=CustodyCodec::Decode(Unhex(row[3]));inspect(std::stoull(row[0]),Number(row[1]),decoded.values.item_id,room?std::stoull(row[4]):0);}};
  collect(false);collect(true);return {std::move(out),Error::None};
 }catch(const TrophyBenefits::Detail::Failure& e){return {{},e.error};}catch(...){return {{},Error::DatabaseFailure};}
}
}
#endif
